import assert from 'node:assert/strict';
import fs from 'node:fs/promises';
import path from 'node:path';
import {fileURLToPath} from 'node:url';
import {spawn} from 'node:child_process';
import {calibrateGroups, evaluateGroup} from './noise-groups.mjs';

const root = fileURLToPath(new URL('../', import.meta.url));
const mode = process.argv[2];
assert.ok(['--preflight', '--run'].includes(mode), 'Use --preflight or --run');
const protocol = JSON.parse(await fs.readFile(root + 'protocol.json', 'utf8'));
assert.equal(process.version, protocol.node);
assert.equal(process.env.TMPDIR, root.slice(0, -1) + '/tmp');
for (const key of ['WSE_BENCH_CPU_PROFILE_DIR', 'WSE_BENCH_BUFFER_BYTES', 'WSE_BENCH_WORKLOADS', 'WSE_BENCH_MODES']) {
  assert.equal(process.env[key], undefined, 'Unexpected benchmark override: ' + key);
}
const lock = root + 'active.lock';
await fs.mkdir(lock);
const runId = new Date().toISOString().replaceAll(':', '-');
const output = root + 'runs/' + (mode === '--run' ? 'measurement-' : 'preflight-') + runId;
await fs.mkdir(output);
const median = values => {
  assert.ok(values.length);
  const sorted = [...values].sort((a, b) => a - b);
  return (sorted[(sorted.length - 1) >> 1] + sorted[sorted.length >> 1]) / 2;
};
function interval(values) {
  let state = protocol.statistics.bootstrapSeed;
  const random = () => { state ^= state << 13; state ^= state >>> 17; state ^= state << 5; return (state >>> 0) / 4294967296; };
  const samples = Array.from({length: protocol.statistics.bootstrapResamples}, () =>
    median(Array.from({length: values.length}, () => values[Math.floor(random() * values.length)]))).sort((a, b) => a - b);
  const quantile = p => { const at = p * (samples.length - 1), low = Math.floor(at); return samples[low] + (samples[Math.ceil(at)] - samples[low]) * (at - low); };
  return {median: median(values), interval95: [quantile(.025), quantile(.975)]};
}
async function execute(suite, round, variant, samples, phase = 'measurement') {
  const name = variant === 0 ? 'legacy' : 'current';
  const entry = root + `variants/${name}/lib/index.js`;
  const args = suite === 'synthetic' ? [root + 'harness/benchmark-small.mjs', entry] :
    [root + 'harness/benchmark-mdn-small.mjs', root + 'fixtures/mdn.html', entry, root + `variants/${name}/mdn/life-cycle.js`];
  const child = spawn(process.execPath, ['--expose-gc', ...args], {
    env: {...process.env, WSE_BENCH_SAMPLES: String(samples)}, stdio: ['ignore', 'pipe', 'pipe']});
  let stdout = '', stderr = '';
  child.stdout.on('data', chunk => { stdout += chunk; });
  child.stderr.on('data', chunk => { stderr += chunk; });
  let timedOut = false;
  const timer = setTimeout(() => { timedOut = true; child.kill('SIGTERM'); }, 120000);
  let code;
  try { code = await new Promise((resolve, reject) => { child.once('error', reject); child.once('close', resolve); }); }
  finally { clearTimeout(timer); }
  const stem = `${output}/${phase === 'calibration' ? 'calibration-' : ''}${suite}-${round}-${variant}`;
  await fs.writeFile(stem + '.log', stderr);
  await fs.writeFile(stem + '.json', stdout);
  assert.equal(timedOut, false, 'Child timed out: ' + stem);
  assert.equal(code, 0, 'Functional failure: ' + stem + '.log');
  const data = JSON.parse(stdout);
  assert.equal(data.node, protocol.node);
  assert.equal(data.results.length, (suite === 'synthetic' ? 8 : 1) * samples);
  return data.results.map(row => ({...row, round, variant,
    case: suite === 'synthetic' ? row.mode + '/' + row.workload : 'SingleThreadDownloader/mdn',
    totalMs: row.totalMs ?? row.ms}));
}
const record = {mode, protocol, output, startedAt: new Date().toISOString(), suites: []};
try {
  if (mode === '--run') {
    const verify = spawn('python3', [root + 'scripts/fingerprint.py', '--verify'], {stdio: 'inherit'});
    assert.equal(await new Promise((resolve, reject) => { verify.once('error', reject); verify.once('close', resolve); }), 0);
    assert.equal(JSON.parse(await fs.readFile(root + 'READY.json')).status, 'ready');
  }
  for (const suite of protocol.suites) {
    const calibration = [], rows = [], order = [];
    let thresholds, groupMaxima;
    if (mode === '--run') {
      for (let round = 0; round < protocol.noise.calibrationGroupsPerSuite; round++) {
        const sequence = [0, 1, 2]; sequence.push(...sequence.splice(0, round));
        for (const variant of sequence) {
          calibration.push(...await execute(suite, round, variant,
            protocol.noise.calibrationSamplesPerProcess, 'calibration'));
          const event = {phase: 'calibration', suite, round: round + 1,
            rounds: protocol.noise.calibrationGroupsPerSuite, variant: protocol.variants[variant], finishedAt: new Date().toISOString()};
          await fs.appendFile(output + '/progress.jsonl', JSON.stringify(event) + '\n');
          console.log(JSON.stringify(event));
        }
      }
      for (const key of new Set(calibration.map(row => row.case))) {
        assert.equal(new Set(calibration.filter(row => row.case === key).map(row => row.sha256)).size, 1,
          'Calibration output mismatch: ' + key);
      }
      ({thresholds, groupMaxima} = calibrateGroups(calibration,
        protocol.noise.calibrationGroupsPerSuite, protocol.noise.thresholdMultiplier));
      await fs.writeFile(output + '/' + suite + '-calibration.json', JSON.stringify({calibration, groupMaxima, thresholds}, null, 2));
      console.log(JSON.stringify({phase: 'thresholds-frozen', suite, thresholds}));
    }
    const rounds = mode === '--run' ? protocol.rounds : 1;
    for (let round = 0; round < rounds; round++) {
      const sequence = [0, 1, 2]; sequence.push(...sequence.splice(0, round % 3));
